import React, { useState, useContext } from "react";
import { View, TextInput, Button, StyleSheet, Text, Alert } from "react-native";
import {
  createUserWithEmailAndPassword,
  getAuth,
  signInWithEmailAndPassword,
} from "firebase/auth";
import { initializeApp } from "@firebase/app";
import { firebaseConfig } from "../../firebase.config";
import { AuthContext } from "../../AuthContext";
import axios from "axios";

const LoginScreen = () => {
  const URI = process.env.MONGODB_URI
    ? process.env.MONGODB_URI
    : "http://localhost:4000/api/";

  const [registro, setRegistro] = useState(false);
  const { setIsAuthenticated } = useContext(AuthContext);
  const { setUser } = useContext(AuthContext);
  const { setUserData } = useContext(AuthContext);

  const app = initializeApp(firebaseConfig);
  const auth = getAuth(app);

  //Constructor para usuario default
  const [nombre, setNombre] = useState("");
  const [apellido, setApellido] = useState("");
  const [telefono, setTelefono] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const Usuario = {
    nombre: nombre.text,
    apellido: apellido.text,
    telefono: telefono.text,
    email: email.text,
    direccion: "Sin asignar",
    contacto: "Sin asignar",
    foto: "",
    calificacion: "Sin calificación",
    reportes: 0,
    estatus: 1,
  };
  const handleCreateAccount = () => {
    createUserWithEmailAndPassword(auth, email.text, password.text)
      .then((userCredential) => {
        // Signed in
        const user = userCredential.user;
        console.log(user);
        Alert.alert(`Usuario creado`, `Bienvenido ${user.email}`);
        setRegistro(!registro);
      })
      .catch((error) => {
        Alert.alert(error.message);
      });
  };
  const [usuario, setUsuario] = useState(Usuario);
  //Función para guardar los datos del usuario en mongo
  const guardarData = async (e) => {
    Alert.alert("Mongodb","Registrando usuario...");
    //Obtener datos ingresados por el usuario
    const newUser = {
      nombre: usuario.nombre,
      apellido: usuario.apellido,
      telefono: usuario.telefono,
      email: usuario.email,
      direccion: usuario.direccion,
      contacto: usuario.contacto,
      foto: usuario.foto,
      calificacion: usuario.calificacion,
      reportes: usuario.reportes,
      estatus: usuario.estatus,
    };
    try {
      //Enviar una solicitud POST para guardar los datos en la base de datos
      await axios.post(`${URI}usuarios`, newUser);
      setUsuario({ ...Usuario }); //Actualizar el estado del usuario
      Alert.alert("Mongodb","Usuario registrado con éxito");
      handleCreateAccount();
    } catch (error) {
      Alert.alert(error.message);
    }
  };

  const handleLogin = () => {
    signInWithEmailAndPassword(auth, email.text, password.text)
      .then((userCredential) => {
        // Signed in
        console.log(user);
        CargarDatos(userCredential.user);
      })
      .catch((error) => {
        Alert.alert(error.message);
      });
  };
  //Cargar datos del usuario a todos los componentes
  async function CargarDatos(user) {
    const campoBuscado = email.text; //Correo del usuario
    const res = await axios.get(`${URI}usuarios/${campoBuscado}`);
    const InfoUsuario = res.data;
    setUserData(InfoUsuario);
    setUser(user);
    setIsAuthenticated(true);
    //guardar usuario en memoria local
    //localStorage.setItem("email", JSON.stringify(InfoUsuario.email));
  }

  return (
    <View style={styles.container} className="bg-white dark:bg-black">
      {registro ? (
        <View>
          <Text style={styles.title} className=" dark:text-white">
            Registrarse
          </Text>
          <TextInput
            placeholder="Nombre"
            name="nombre"
            onChangeText={(text) => setNombre({ text })}
            className="dark:bg-white"
            style={styles.input}
          />
          <TextInput
            placeholder="Apellido"
            name="apellido"
            onChangeText={(text) => setApellido({ text })}
            className="dark:bg-white"
            style={styles.input}
          />
          <TextInput
            placeholder="Telefono"
            name="telefono"
            onChangeText={(text) => setTelefono({ text })}
            className="dark:bg-white"
            style={styles.input}
          />
          <TextInput
            placeholder="Correo electrónico"
            name="email"
            onChangeText={(text) => setEmail({ text })}
            className="dark:bg-white"
            style={styles.input}
          />
          <TextInput
            placeholder="Contraseña"
            name="password"
            secureTextEntry
            onChangeText={(text) => setPassword({ text })}
            style={styles.input}
            className="dark:bg-white"
          />
          <Button title="Registrarse" onPress={guardarData} />
          <Button
            title="Iniciar sesión"
            onPress={() => {
              setRegistro(!registro);
            }}
          />
        </View>
      ) : (
        <View>
          <Text style={styles.title} className=" dark:text-white">
            Iniciar sesión
          </Text>
          <TextInput
            onChangeText={(text) => setEmail({ text })}
            style={styles.input}
            placeholder="Correo electrónico"
            className="dark:bg-white"
          />
          <TextInput
            onChangeText={(text) => setPassword({ text })}
            style={styles.input}
            placeholder="Contraseña"
            className="dark:bg-white"
            secureTextEntry
          />
          <Button title="Iniciar sesión" onPress={handleLogin} />
          <Button
            title="Registrarse"
            onPress={() => {
              setRegistro(!registro);
            }}
          />
        </View>
      )}
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    justifyContent: "center",
    alignItems: "center",
    padding: 20,
  },
  title: {
    fontSize: 24,
    fontWeight: "bold",
    marginBottom: 20,
  },
  input: {
    borderWidth: 1,
    borderColor: "#ccc",
    borderRadius: 5,
    padding: 10,
    marginVertical: 10,
    minWidth: "80%",
  },
  error: {
    color: "red",
    marginBottom: 10,
  },
});

export default LoginScreen;
